style.css:
@-moz-document domain("mobilism.org"), domain("mobilism.me") {
/* ----------------------------------------------------------------
     1. Base
     ---------------------------------------------------------------- */

  :root {
    color-scheme: dark;
  }

  html {
    background-color: #0b0e12 !important;
  }

  body#phpbb,
  body {
    background-color: #0b0e12 !important;
    background-image: none !important;
    color: #c4cdd6 !important;
  }

  #wrap,
  #simple-wrap,
  .corners {
    background-color: transparent !important;
  }

  #content-forum {
    background-color: #14181d !important;
  }

  main,
  article,
  section,
  aside,
  .container,
  .container-fluid,
  .row,
  .row-fluid {
    background-color: transparent !important;
  }

  /* ----------------------------------------------------------------
     2. Borders — broad softening pass
     ---------------------------------------------------------------- */

  #content-forum *,
  footer *,
  .jumbotron *,
  .bs-docs-social * {
    border-color: #262c33;
  }

  hr {
    border-top-color: #262c33 !important;
    border-bottom-color: transparent !important;
    background-color: transparent !important;
  }

  /* ----------------------------------------------------------------
     3. Typography
     ---------------------------------------------------------------- */

  h1, h2, h3, h4, h5, h6,
  .page-header,
  legend {
    color: #e6edf3 !important;
  }

  legend,
  .page-header {
    border-bottom-color: #262c33 !important;
  }

  p, li, dd, dt, td, th, label, small, strong, em, span {
    border-color: #262c33;
  }

  .muted,
  small.sub-stats-info,
  .sub-stats-info,
  .rank-title,
  blockquote small {
    color: #8b949e !important;
  }

  /* ----------------------------------------------------------------
     4. Links
     ---------------------------------------------------------------- */

  a,
  a:link,
  a:visited {
    color: #5fb0e6;
  }

  a:hover,
  a:focus,
  a:active {
    color: #9bd4ff;
  }

  .forumtitle,
  .topictitle,
  a.postlink,
  .content a,
  .side-segment a,
  #footerContent a {
    color: #5fb0e6 !important;
  }

  .forumtitle:hover,
  .topictitle:hover,
  a.postlink:hover,
  .content a:hover,
  .side-segment a:hover,
  #footerContent a:hover {
    color: #9bd4ff !important;
  }

  /* ----------------------------------------------------------------
     5. Masthead / brand header
     ---------------------------------------------------------------- */

  .jumbotron,
  .jumbotron.masthead,
  .jumbotron .header,
  header.header,
  header .topArea {
    background-color: #0d2337 !important;
    background-image: none !important;
  }

  header .leftArea .logo,
  .mainnav > ul > li > a,
  header .leftArea .site-info {
    color: #e6edf3 !important;
  }

  /* the display "M" ships black on the blue band — keep the two-tone
     wordmark by tinting it with the brand accent instead */
  .logo span,
  .logo-transition a::before,
  .logo-transition a::after {
    color: #5fb0e6 !important;
    text-shadow: none !important;
  }

  header .leftArea .site-info {
    color: #a9b6c2 !important;
  }

  .mainnav > ul > li > a:hover,
  .mainnav > ul > li > a:focus {
    color: #9bd4ff !important;
  }

  .mainnav > ul > li > a > i {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  .mainnav > ul > li > p {
    color: #8b949e !important;
  }

  /* full-bleed spacer strip behind the content column — its rules only
     ever show in the page gutters */
  .bs-docs-social {
    background-color: #0b0e12 !important;
    border-top-color: transparent !important;
    border-bottom-color: transparent !important;
  }

  /* ----------------------------------------------------------------
     6. Nav flyout menus (BOOKS / APPS)
     ---------------------------------------------------------------- */

  .submenu,
  .mainnav .submenu,
  ul.submenu.greydout {
    background-color: #1c2128 !important;
    border-bottom-color: #169fe6 !important;
    box-shadow: 0 8px 15px rgba(0, 0, 0, 0.6) !important;
  }

  .submenu li > a {
    color: #c4cdd6 !important;
  }

  .submenu li:hover > a {
    color: #9bd4ff !important;
  }

  .submenu li > span {
    background-color: #2d333b !important;
  }

  .submenu li,
  .submenu > li {
    border-color: #2d333b !important;
  }

  .submenu li:hover > span {
    background-color: #169fe6 !important;
  }

  .flexnav,
  .flexnav li,
  .nav-collapse,
  .nav-collapse .nav {
    background-color: #0d2337 !important;
  }

  /* the phone nav paints each level a progressively lighter grey */
  .flexnav li a,
  .nav-collapse .nav a {
    background: none repeat scroll 0 0 #1c2128 !important;
    color: #e6edf3 !important;
    border-bottom-color: rgba(0, 0, 0, 0.5) !important;
  }

  .flexnav li ul li a {
    background: #232a33 !important;
  }

  .flexnav ul li ul li a {
    background: #2a323c !important;
  }

  .flexnav ul li ul li ul li a {
    background: #323b46 !important;
  }

  .flexnav li a:hover {
    background-color: #2e3742 !important;
    color: #9bd4ff !important;
  }

  .flexnav .touch-button {
    background: rgba(255, 255, 255, 0.06) !important;
  }

  .flexnav .touch-button .navicon {
    color: #c4cdd6 !important;
  }

  .navBtn {
    background-color: #14456e !important;
  }

  .navBtn a,
  .navBtn span {
    color: #e6edf3 !important;
  }

  .navBtn a:hover {
    color: #9bd4ff !important;
  }

  /* ----------------------------------------------------------------
     7. Search boxes
     ---------------------------------------------------------------- */

  .search-box form input,
  .search-mobilism input,
  #search_keywords,
  #forum-search input,
  #topic-search input {
    background-color: #101d2a !important;
    color: #e6edf3 !important;
    border: 1px solid #24384a !important;
    box-shadow: none !important;
  }

  .search-box form input::placeholder,
  #search_keywords::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* ----------------------------------------------------------------
     8. Forum / topic tables
     ---------------------------------------------------------------- */

  .table,
  .table-white,
  table.table,
  .footable {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  .table-white {
    background: none repeat scroll 0 0 #14181d !important;
  }

  .table-primary,
  .table-primary.table-bordered tbody td,
  .table-bordered,
  .table-bordered td,
  .table-bordered th {
    border-color: #262c33 !important;
  }

  .table th,
  .table td {
    border-top-color: #262c33 !important;
  }

  .table-primary thead th,
  .table-white thead th,
  .table thead th {
    background-color: #10314c !important;
    border-color: #10314c !important;
    color: #dceaf6 !important;
  }

  .table-primary thead th a,
  .table thead th a {
    color: #dceaf6 !important;
  }

  .table-primary thead th i,
  .table thead th i {
    color: #9ec7e8 !important;
  }

  .table-primary tbody td,
  .table tbody td {
    color: #c4cdd6 !important;
  }

  .table-primary tbody td i,
  .table tbody td i {
    color: #8b949e !important;
  }

  .table-hover tbody tr:hover td,
  .table-hover tbody tr:hover th,
  .table-primary tbody tr.selectable:hover td {
    background-color: #1e242c !important;
    box-shadow: inset 0 0 0 1px #2d333b !important;
  }

  .table-primary tbody tr.selected td {
    background-color: #22303d !important;
    box-shadow: inset 0 0 0 1px #2d333b !important;
  }

  /* memberlist and other striped tables alternate on a near-white row */
  .table-striped tbody > tr:nth-child(odd) > td,
  .table-striped tbody > tr:nth-child(odd) > th,
  .table-striped tbody > tr:nth-child(2n+1) > td,
  #memberlist tbody > tr > td,
  #memberlist tbody > tr > th {
    background-color: #191e25 !important;
  }

  .table-striped tbody > tr:nth-child(even) > td,
  #memberlist tbody > tr:nth-child(even) > td {
    background-color: #14181d !important;
  }

  td.stats-color,
  .stats-color {
    background-color: #16232f !important;
  }

  td.last-color,
  .last-color {
    background-color: #1a1f26 !important;
  }

  .sub-stats {
    color: #5fb0e6 !important;
  }

  /* footable's phone breakpoint: row-expand toggle and detail rows */
  .footable.breakpoint > tbody > tr > td > span.footable-toggle,
  span.footable-toggle {
    background: none repeat scroll 0 0 #262c33 !important;
    color: #c4cdd6 !important;
  }

  .footable.breakpoint > tbody > tr.footable-row-detail,
  .footable.breakpoint > tbody > tr > td.footable-cell-detail {
    background: none repeat scroll 0 0 #1a1f26 !important;
  }

  .footable-odd {
    background-color: #191e25 !important;
  }

  /* status icons ship as opaque light rasters — flip them to dark
     while preserving the hue that encodes read / sticky / announce */
  td .row-icon,
  .row-icon,
  .topic-icon {
    filter: invert(1) hue-rotate(180deg);
  }

  /* ----------------------------------------------------------------
     9. Wells, panels, posts
     ---------------------------------------------------------------- */

  .well,
  .well-small,
  .well-large,
  .mobil-default {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    box-shadow: none !important;
    color: #c4cdd6 !important;
  }

  .well blockquote {
    border-color: #2d333b !important;
  }

  .postbody,
  .postbody .content {
    color: #c4cdd6 !important;
  }

  .postbody .content strong,
  .postbody .content b {
    color: #e6edf3 !important;
  }

  .blue-bar {
    background-color: transparent !important;
  }

  .user-profile-tab,
  .user-profile-avatar,
  .info-block,
  .list-group,
  .list-group-item {
    background-color: transparent !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .list-group-item strong {
    color: #8b949e !important;
  }

  .avatar-frame img,
  .postbody img.avatar,
  img.avatar {
    border-color: #2d333b !important;
    box-shadow: 0 0 3px rgba(0, 0, 0, 0.6) !important;
  }

  /* the page heading's green rule is drawn with currentColor, so
     recolouring the h3 erases it — pin the accent explicitly */
  .page-category h3,
  .page-category-topic h3 {
    border-bottom-color: #8cc63f !important;
  }

  .page-category h3,
  .page-category h3 a,
  .page-category-topic h3,
  .page-category-topic h3 a {
    color: #b6c2cd !important;
  }

  /* phone-only post byline */
  .timepost {
    color: #9aa5b1 !important;
  }

  .timepost a,
  .timepost strong a {
    color: #5fb0e6 !important;
  }

  /* ----------------------------------------------------------------
     10. Quotes, code, attachments, signatures
     ---------------------------------------------------------------- */

  blockquote {
    border-left-color: #2d333b !important;
    color: #b6c2cd !important;
  }

  .postbody blockquote,
  .content blockquote {
    background-color: #161b22 !important;
    border-left-color: #3a424c !important;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.45) !important;
    color: #c4cdd6 !important;
  }

  .postbody blockquote cite {
    color: #8b949e !important;
  }

  .postbody blockquote > i {
    color: #4a545f !important;
  }

  /* post separator: a hairline rule with a centred glyph whose own
     background masks the line — it has to match the post surface */
  p.separator::before {
    background-color: #2d333b !important;
  }

  p.separator i {
    background-color: #1c2128 !important;
    color: #6e7781 !important;
  }

  blockquote.pull-right {
    border-right-color: #2d333b !important;
  }

  blockquote cite,
  blockquote small {
    color: #8b949e !important;
  }

  .codebox,
  .attachbox,
  .pm-message .attachbox {
    background-color: #161b22 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .codebox span {
    border-bottom-color: #2d333b !important;
    color: #8b949e !important;
  }

  .codebox code {
    color: #c9d1d9 !important;
    background-color: transparent !important;
    border: 0 !important;
  }

  .attachbox p {
    color: #8b949e !important;
  }

  .attach-image img,
  .thumbnail,
  .thumbnail img {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: none !important;
  }

  .signature {
    border-top-color: #2d333b !important;
    color: #a9b6c2 !important;
  }

  pre,
  code,
  kbd,
  samp,
  tt {
    background-color: #161b22 !important;
    border-color: #2d333b !important;
    color: #c9d1d9 !important;
  }

  code {
    color: #ff9d96 !important;
  }

  /* ----------------------------------------------------------------
     11. Buttons
     ---------------------------------------------------------------- */

  .btn,
  .btn:link,
  .btn:visited,
  button.btn,
  input[type="submit"],
  input[type="button"],
  input[type="reset"],
  .dropdown-toggle,
  .btn-default {
    background-color: #21262e !important;
    background-image: linear-gradient(#252b34, #1b2027) !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
    text-shadow: none !important;
    box-shadow: none !important;
  }

  .btn:hover,
  .btn:focus,
  .btn.active,
  .btn:active,
  button.btn:hover,
  .dropdown-toggle:hover,
  .dropdown-toggle:focus {
    background-color: #2a313a !important;
    background-image: linear-gradient(#2e3540, #242a32) !important;
    color: #e6edf3 !important;
    border-color: #3a424c !important;
  }

  .btn[disabled],
  .btn.disabled {
    background-image: none !important;
    background-color: #1a1f26 !important;
    color: #6e7781 !important;
  }

  .btn i,
  .btn [class^="icon-"],
  .btn [class*=" icon-"] {
    color: inherit !important;
  }

  /* semantic buttons — keep the hue, drop the brightness */

  .btn-primary,
  .btn-primary:link,
  .btn-primary:visited {
    background-color: #1b4f7d !important;
    background-image: linear-gradient(#1f5c91, #17456c) !important;
    border-color: #23608f !important;
    color: #eaf3fb !important;
    text-shadow: none !important;
  }

  .btn-primary:hover,
  .btn-primary:focus,
  .btn-primary:active,
  .btn-primary.active {
    background-color: #22608f !important;
    background-image: linear-gradient(#2870a6, #1d5480) !important;
    color: #f2f8fd !important;
  }

  .btn-success,
  .btn-success:link,
  .btn-success:visited {
    background-color: #2f6b39 !important;
    background-image: linear-gradient(#397f45, #275c30) !important;
    border-color: #367a41 !important;
    color: #e9f6ec !important;
    text-shadow: none !important;
  }

  .btn-success:hover,
  .btn-success:focus,
  .btn-success:active {
    background-color: #3a8145 !important;
    background-image: linear-gradient(#43944f, #2f6b39) !important;
    color: #f3fbf5 !important;
  }

  .btn-danger,
  .btn-danger:link,
  .btn-danger:visited {
    background-color: #8a3630 !important;
    background-image: linear-gradient(#a03f38, #742c27) !important;
    border-color: #9c3e37 !important;
    color: #fdeceb !important;
    text-shadow: none !important;
  }

  .btn-danger:hover,
  .btn-danger:focus,
  .btn-danger:active {
    background-color: #a34840 !important;
    background-image: linear-gradient(#b85149, #8a3630) !important;
    color: #fff4f3 !important;
  }

  .btn-warning,
  .btn-warning:link,
  .btn-warning:visited {
    background-color: #8a5f14 !important;
    background-image: linear-gradient(#a07018, #6f4c10) !important;
    border-color: #9c6c17 !important;
    color: #fdf3e2 !important;
    text-shadow: none !important;
  }

  .btn-warning:hover,
  .btn-warning:focus,
  .btn-warning:active {
    background-color: #a3721c !important;
    background-image: linear-gradient(#b88220, #8a5f14) !important;
    color: #fff9ef !important;
  }

  .btn-info,
  .btn-info:link,
  .btn-info:visited {
    background-color: #1f5f6d !important;
    background-image: linear-gradient(#25707f, #1a505c) !important;
    border-color: #26707f !important;
    color: #e7f6f9 !important;
    text-shadow: none !important;
  }

  .btn-info:hover,
  .btn-info:focus,
  .btn-info:active {
    background-color: #26707f !important;
    background-image: linear-gradient(#2d8395, #1f5f6d) !important;
    color: #f2fbfd !important;
  }

  .btn-inverse,
  .btn-inverse:link,
  .btn-inverse:visited {
    background-color: #262c33 !important;
    background-image: linear-gradient(#2c333b, #20262d) !important;
    border-color: #343c45 !important;
    color: #e6edf3 !important;
    text-shadow: none !important;
  }

  .btn-link {
    background-color: transparent !important;
    background-image: none !important;
    border-color: transparent !important;
    color: #5fb0e6 !important;
  }

  /* ----------------------------------------------------------------
     12. Forms
     ---------------------------------------------------------------- */

  input[type="text"],
  input[type="password"],
  input[type="email"],
  input[type="url"],
  input[type="tel"],
  input[type="number"],
  input[type="search"],
  input[type="date"],
  input[type="datetime"],
  input[type="datetime-local"],
  input[type="month"],
  input[type="time"],
  input[type="week"],
  input[type="color"],
  textarea,
  select,
  .uneditable-input,
  .inputbox {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
    box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.3) !important;
  }

  input:focus,
  textarea:focus,
  select:focus {
    border-color: #3d7ba8 !important;
    box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.3), 0 0 6px rgba(95, 176, 230, 0.35) !important;
    outline: none !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* checkboxes and radios are a light 4-cell raster sprite drawn on the
     label's ::before — flipped so the box reads dark and the tick light */
  input[type="checkbox"] + label::before,
  input[type="radio"] + label::before {
    filter: invert(1) hue-rotate(180deg);
  }

  input[type="checkbox"],
  input[type="radio"] {
    accent-color: #2b7bb9;
    border-color: #2d333b !important;
  }

  option,
  optgroup {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  .control-label,
  .help-block,
  .help-inline,
  .radio,
  .checkbox,
  fieldset legend {
    color: #c4cdd6 !important;
  }

  .help-block,
  .help-inline {
    color: #8b949e !important;
  }

  .input-append .add-on,
  .input-prepend .add-on {
    background-color: #21262e !important;
    border-color: #2d333b !important;
    color: #8b949e !important;
    text-shadow: none !important;
  }

  /* these sit ON TOP of the field, not beside it — colour only */
  .input-icon i {
    background-color: transparent !important;
    color: #8b949e !important;
  }

  .uneditable-input {
    background-color: #161b22 !important;
  }

  .control-group.error .control-label,
  .control-group.error .help-block,
  .control-group.error .help-inline,
  .control-group.error .checkbox,
  .control-group.error .radio,
  .control-group.error input,
  .control-group.error select,
  .control-group.error textarea {
    color: #ff9d96 !important;
    border-color: #8a3630 !important;
  }

  .control-group.success .control-label,
  .control-group.success .help-block,
  .control-group.success .help-inline,
  .control-group.success .checkbox,
  .control-group.success .radio {
    color: #6fc47e !important;
  }

  .control-group.warning .control-label,
  .control-group.warning .help-block,
  .control-group.warning .help-inline {
    color: #e0b168 !important;
  }

  .form-actions {
    background-color: #161b22 !important;
    border-top-color: #262c33 !important;
  }

  /* ----------------------------------------------------------------
     13. Dropdowns, popovers, modals, tooltips
     ---------------------------------------------------------------- */

  .dropdown-menu,
  .dropdown-menu.inner,
  .bootstrap-select .dropdown-menu,
  .typeahead.dropdown-menu {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
    box-shadow: 0 5px 12px rgba(0, 0, 0, 0.6) !important;
  }

  .dropdown-menu > li > a,
  .dropdown-menu li a {
    color: #c4cdd6 !important;
    text-shadow: none !important;
  }

  .dropdown-menu > li > a:hover,
  .dropdown-menu > li > a:focus,
  .dropdown-menu li:hover,
  .dropdown-menu li:hover > a,
  .dropdown-menu > .active > a,
  .dropdown-menu > .active > a:hover,
  .dropdown-menu > .active > a:focus {
    background-color: #263039 !important;
    background-image: none !important;
    color: #9bd4ff !important;
    text-shadow: none !important;
  }

  .dropdown-menu > .disabled > a {
    color: #6e7781 !important;
  }

  .dropdown-menu .divider {
    background-color: #2d333b !important;
    border-bottom-color: transparent !important;
  }

  /* bootstrap-select mounts its menu OUTSIDE #content-forum, so the broad
     border pass never reaches the #e4e4e4 hairline between its options */
  .dropdown-menu li,
  .dropdown-menu > li,
  .dropdown-menu .dropdown-menu li {
    border-top-color: #2d333b !important;
    border-bottom-color: #2d333b !important;
  }

  .dropdown-submenu > a::after {
    border-left-color: #6e7781 !important;
  }

  .dropdown-submenu:hover > a::after {
    border-left-color: #9bd4ff !important;
  }

  /* the caret is a border triangle — its transparent sides must stay
     transparent or the broad border pass renders it as a rectangle */
  .caret {
    border-top-color: #8b949e !important;
    border-right-color: transparent !important;
    border-bottom-color: transparent !important;
    border-left-color: transparent !important;
  }

